import {
  InvalidPromptError,
  LanguageModelV4Prompt,
  UnsupportedFunctionalityError,
} from "@ai-sdk/provider";

export function convertToOllamaCompletionPrompt({
  prompt,
  user = "user",
  assistant = "assistant",
}: {
  prompt: LanguageModelV4Prompt;
  user?: string;
  assistant?: string;
}): {
  prompt: string;
  stopSequences?: string[];
} {
  // transform to a chat message format:
  let text = "";

  // if first message is a system message, add it to the text:
  if (prompt[0].role === "system") {
    text += `${prompt[0].content}\n\n`;
    prompt = prompt.slice(1);
  }

  for (const { role, content } of prompt) {
    switch (role) {
      case "system": {
        throw new InvalidPromptError({
          message: "Unexpected system message in prompt: ${content}",
          prompt,
        });
      }

      case "user": {
        const userMessage = content
          .map((part) => {
            switch (part.type) {
              case "text": {
                return part.text;
              }
              case "file": {
                throw new UnsupportedFunctionalityError({
                  functionality: "file parts in completion prompts",
                });
              }
              default: {
                const _exhaustiveCheck: never = part;
                throw new Error(`Unsupported user part: ${_exhaustiveCheck}`);
              }
            }
          })
          .filter(Boolean)
          .join("");

        text += `${user}:\n${userMessage}\n\n`;
        break;
      }

      case "assistant": {
        const assistantMessage = content
          .map((part) => {
            switch (part.type) {
              case "text": {
                return part.text;
              }
              case "reasoning": {
                return part.text;
              }
              case "tool-call": {
                throw new UnsupportedFunctionalityError({
                  functionality: "tool-call messages",
                });
              }
              case "file":
              case "reasoning-file":
              case "custom":
              case "tool-result": {
                throw new UnsupportedFunctionalityError({
                  functionality: `${part.type} parts in completion prompts`,
                });
              }
              default: {
                const _exhaustiveCheck: never = part;
                throw new Error(
                  `Unsupported assistant part: ${_exhaustiveCheck}`,
                );
              }
            }
          })
          .join("");

        text += `${assistant}:\n${assistantMessage}\n\n`;
        break;
      }

      case "tool": {
        throw new UnsupportedFunctionalityError({
          functionality: "tool messages",
        });
      }

      default: {
        const _exhaustiveCheck: never = role;
        throw new Error(`Unsupported role: ${_exhaustiveCheck}`);
      }
    }
  }

  // Assistant message prefix:
  text += `${assistant}:\n`;

  return {
    prompt: text,
    stopSequences: [`\n${user}:`],
  };
}
